def calculate_k(A, B, threshold):
    K = 0
    for m in A:
        for n in B:
            if abs(m - n) <= threshold:
                K += 1
    return K

# Parameters
N_A = 20
N_B = 22
THRESHOLD = 1000

# Test a range of relative shifts S (where B is shifted by S relative to A)
# A = {0, 1, ..., 19}
# B = {S, S+1, ..., S+21}
shifts_to_test = range(-50, 51)
results = {}

for S in shifts_to_test:
    A = list(range(N_A))
    B = list(range(S, S + N_B))
    K = calculate_k(A, B, THRESHOLD)
    results[S] = K

# Find the maximum K and the corresponding shift
max_K = 0
best_shift = 0
for S, K in results.items():
    if K > max_K:
        max_K = K
        best_shift = S

print(f"Maximum K found: {max_K}")
print(f"Relative shift that yields maximum K: {best_shift}")

